{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2181-03-17 09:00:00",
      "speaker": "Doctor",
      "text": "Good morning. I’m Dr. Lee, one of your hospital doctors. You came in last night with right-sided abdominal pain. Can you tell me more about it?"
    },
    {
      "turn_number": 2,
      "time": "2181-03-17 09:02:00",
      "speaker": "Patient",
      "text": "Yes, it started suddenly the day before yesterday. It’s a dull ache in the upper right side, and it radiates a bit to my back. It’s constant, not worse with eating."
    },
    {
      "turn_number": 3,
      "time": "2181-03-17 09:04:00",
      "speaker": "Doctor",
      "text": "I see. Any nausea, vomiting, or changes in bowel habits?"
    },
    {
      "turn_number": 4,
      "time": "2181-03-17 09:05:00",
      "speaker": "Patient",
      "text": "No, no vomiting or diarrhea. I’ve just been eating less because of the pain. I did feel chills at home and had a low fever once."
    },
    {
      "turn_number": 5,
      "time": "2181-03-17 09:07:00",
      "speaker": "Doctor",
      "text": "Okay. We’ve reviewed your labs and imaging. Your liver enzymes are elevated—ALT and AST are higher than normal. That’s a sign your liver might be irritated."
    },
    {
      "turn_number": 6,
      "time": "2181-03-17 09:09:00",
      "speaker": "Patient",
      "text": "Is that from my transplant? I’ve had issues before."
    },
    {
      "turn_number": 7,
      "time": "2181-03-17 09:11:00",
      "speaker": "Doctor",
      "text": "Possibly. Your CT and ultrasound show the liver blood vessels are open and no blockages. But we can’t rule out rejection without a biopsy."
    },
    {
      "turn_number": 8,
      "time": "2181-03-17 09:13:00",
      "speaker": "Patient",
      "text": "A biopsy? Is that safe with my history?"
    },
    {
      "turn_number": 9,
      "time": "2181-03-17 09:15:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll do a transjugular biopsy—through the neck vein. It’s safer for you given your anatomy and blood thinners."
    },
    {
      "turn_number": 10,
      "time": "2181-03-17 09:17:00",
      "speaker": "Patient",
      "text": "Alright, I trust you. When will it happen?"
    },
    {
      "turn_number": 11,
      "time": "2181-03-17 09:19:00",
      "speaker": "Doctor",
      "text": "Tomorrow morning. We’ll keep an eye on your pain and repeat your labs today."
    },
    {
      "turn_number": 12,
      "time": "2181-03-18 10:30:00",
      "speaker": "Doctor",
      "text": "Hi, we just got back from your biopsy. It went well—you tolerated it fine. They took three samples."
    },
    {
      "turn_number": 13,
      "time": "2181-03-18 10:32:00",
      "speaker": "Patient",
      "text": "Any pain afterward? I feel okay."
    },
    {
      "turn_number": 14,
      "time": "2181-03-18 10:34:00",
      "speaker": "Doctor",
      "text": "You’re doing great. There’s a small bandage on your neck. We’ll watch for any bleeding, but it’s very unlikely."
    },
    {
      "turn_number": 15,
      "time": "2181-03-18 10:36:00",
      "speaker": "Patient",
      "text": "When will we know the results?"
    },
    {
      "turn_number": 16,
      "time": "2181-03-18 10:38:00",
      "speaker": "Doctor",
      "text": "Pathology will take a few days. We’re concerned it could be mild rejection, so we’re adjusting your meds just in case."
    },
    {
      "turn_number": 17,
      "time": "2181-03-18 10:40:00",
      "speaker": "Patient",
      "text": "Like what?"
    },
    {
      "turn_number": 18,
      "time": "2181-03-18 10:42:00",
      "speaker": "Doctor",
      "text": "We’re increasing your mycophenolate and cyclosporine. And we’re starting prednisone—60 mg daily—to calm any inflammation."
    },
    {
      "turn_number": 19,
      "time": "2181-03-18 10:44:00",
      "speaker": "Patient",
      "text": "Prednisone? I’ve had mood swings with it before."
    },
    {
      "turn_number": 20,
      "time": "2181-03-18 10:46:00",
      "speaker": "Doctor",
      "text": "We’ll monitor that closely. We’re also starting valganciclovir to prevent viral infections, which can mimic rejection."
    },
    {
      "turn_number": 21,
      "time": "2181-03-20 09:15:00",
      "speaker": "Doctor",
      "text": "The biopsy results are back. They show mild acute rejection—your immune system is slightly attacking the liver."
    },
    {
      "turn_number": 22,
      "time": "2181-03-20 09:17:00",
      "speaker": "Patient",
      "text": "Oh no. Is that serious?"
    },
    {
      "turn_number": 23,
      "time": "2181-03-20 09:19:00",
      "speaker": "Doctor",
      "text": "It’s mild and treatable. We’ve already started the right meds. But your liver enzymes are still rising, which is concerning."
    },
    {
      "turn_number": 24,
      "time": "2181-03-20 09:21:00",
      "speaker": "Patient",
      "text": "Could it be something else?"
    },
    {
      "turn_number": 25,
      "time": "2181-03-20 09:23:00",
      "speaker": "Doctor",
      "text": "We’re checking for infections—CMV, EBV, HSV—but so far, all negative. We may need another biopsy if things don’t improve."
    },
    {
      "turn_number": 26,
      "time": "2181-03-21 14:00:00",
      "speaker": "Patient",
      "text": "I’ve been feeling really anxious and restless. I even had some dark thoughts—nothing serious, but it’s not like me."
    },
    {
      "turn_number": 27,
      "time": "2181-03-21 14:02:00",
      "speaker": "Doctor",
      "text": "That’s likely the steroids. Prednisone can cause mood changes. We’re adding Ativan as needed and starting Seroquel at night to help."
    },
    {
      "turn_number": 28,
      "time": "2181-03-21 14:04:00",
      "speaker": "Patient",
      "text": "Seroquel? I’ve heard that can affect the liver."
    },
    {
      "turn_number": 29,
      "time": "2181-03-21 14:06:00",
      "speaker": "Doctor",
      "text": "It can, but we’ll monitor closely. Your mental health is important, and this combo usually works well."
    },
    {
      "turn_number": 30,
      "time": "2181-03-23 10:00:00",
      "speaker": "Doctor",
      "text": "Your mood seems better. But your liver enzymes are still going up. We’re switching from oral prednisone to IV solumedrol—stronger dose."
    },
    {
      "turn_number": 31,
      "time": "2181-03-23 10:02:00",
      "speaker": "Patient",
      "text": "More steroids? Won’t that make my mood worse?"
    },
    {
      "turn_number": 32,
      "time": "2181-03-23 10:04:00",
      "speaker": "Doctor",
      "text": "Possibly, but we need to control the liver issue. We’re keeping Seroquel and Ativan to help. We’re also holding lisinopril for now—could be contributing."
    },
    {
      "turn_number": 33,
      "time": "2181-03-25 09:30:00",
      "speaker": "Doctor",
      "text": "We’ve given 3 grams of solumedrol. But your LFTs are still high. We think it might not be rejection anymore. We’re scheduling a second biopsy."
    },
    {
      "turn_number": 34,
      "time": "2181-03-25 09:32:00",
      "speaker": "Patient",
      "text": "Another one? So soon?"
    },
    {
      "turn_number": 35,
      "time": "2181-03-25 09:34:00",
      "speaker": "Doctor",
      "text": "Yes, to see if the rejection has responded. We also want to check for drug toxicity or fatty liver."
    },
    {
      "turn_number": 36,
      "time": "2181-03-28 14:00:00",
      "speaker": "Doctor",
      "text": "Biopsy results are in. Good news—no signs of rejection this time. But there’s mild fatty change in the liver."
    },
    {
      "turn_number": 37,
      "time": "2181-03-28 14:02:00",
      "speaker": "Patient",
      "text": "So it’s not rejecting? What caused the enzyme rise?"
    },
    {
      "turn_number": 38,
      "time": "2181-03-28 14:04:00",
      "speaker": "Doctor",
      "text": "We think it’s medication-related. Seroquel and temazepam are more likely to cause liver enzyme changes, especially together. We’ll stop both at discharge."
    },
    {
      "turn_number": 39,
      "time": "2181-03-28 14:06:00",
      "speaker": "Patient",
      "text": "But I need something for sleep. Temazepam helps."
    },
    {
      "turn_number": 40,
      "time": "2181-03-28 14:08:00",
      "speaker": "Doctor",
      "text": "We’ll switch you to lorazepam as needed—it’s safer for your liver. And we’ll keep the Ativan for anxiety if needed."
    },
    {
      "turn_number": 41,
      "time": "2181-03-28 14:10:00",
      "speaker": "Patient",
      "text": "What about the prednisone?"
    },
    {
      "turn_number": 42,
      "time": "2181-03-28 14:12:00",
      "speaker": "Doctor",
      "text": "We’ll continue 20 mg daily for now. Your body needs time to adjust after the rejection scare."
    },
    {
      "turn_number": 43,
      "time": "2181-03-28 14:14:00",
      "speaker": "Patient",
      "text": "And cyclosporine?"
    },
    {
      "turn_number": 44,
      "time": "2181-03-28 14:16:00",
      "speaker": "Doctor",
      "text": "Your level was 262—high, so we’re reducing the dose to 175 mg twice daily. We’ll check it again soon."
    },
    {
      "turn_number": 45,
      "time": "2181-03-28 14:18:00",
      "speaker": "Patient",
      "text": "I’ve been checking my blood sugar. It’s high. Is that the steroids?"
    },
    {
      "turn_number": 46,
      "time": "2181-03-28 14:20:00",
      "speaker": "Doctor",
      "text": "Yes, steroids can raise blood sugar. We’re giving you a sliding scale insulin to use at home. It should improve when the dose is lowered."
    },
    {
      "turn_number": 47,
      "time": "2181-03-28 14:22:00",
      "speaker": "Patient",
      "text": "I’m glad we figured this out. I was so worried."
    },
    {
      "turn_number": 48,
      "time": "2181-03-28 14:24:00",
      "speaker": "Doctor",
      "text": "You’re doing well. Pain is better, labs are stabilizing. We’re planning discharge tomorrow."
    },
    {
      "turn_number": 49,
      "time": "2181-03-29 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. You’re cleared to go home today."
    },
    {
      "turn_number": 50,
      "time": "2181-03-29 08:02:00",
      "speaker": "Patient",
      "text": "Great. What do I need to do next?"
    },
    {
      "turn_number": 51,
      "time": "2181-03-29 08:04:00",
      "speaker": "Doctor",
      "text": "First, blood work in three days—liver tests, cyclosporine level, and basic labs. They’ll be faxed to your transplant team."
    },
    {
      "turn_number": 52,
      "time": "2181-03-29 08:06:00",
      "speaker": "Patient",
      "text": "And my meds?"
    },
    {
      "turn_number": 53,
      "time": "2181-03-29 08:08:00",
      "speaker": "Doctor",
      "text": "Continue prednisone 20 mg daily, cyclosporine 175 mg twice daily, mycophenolate 720 mg twice daily, and valganciclovir daily for three months."
    },
    {
      "turn_number": 54,
      "time": "2181-03-29 08:10:00",
      "speaker": "Patient",
      "text": "And no more Seroquel or temazepam?"
    },
    {
      "turn_number": 55,
      "time": "2181-03-29 08:12:00",
      "speaker": "Doctor",
      "text": "Correct. Use lorazepam for sleep if needed. And the insulin sliding scale—check your blood sugar four times a day."
    },
    {
      "turn_number": 56,
      "time": "2181-03-29 08:14:00",
      "speaker": "Patient",
      "text": "When do I see the liver doctor?"
    },
    {
      "turn_number": 57,
      "time": "2181-03-29 08:16:00",
      "speaker": "Doctor",
      "text": "In one week. They’ll review your labs and adjust meds if needed. If your pain returns or you run a fever, call them right away."
    },
    {
      "turn_number": 58,
      "time": "2181-03-29 08:18:00",
      "speaker": "Patient",
      "text": "I will. Thank you for explaining everything."
    },
    {
      "turn_number": 59,
      "time": "2181-03-29 08:20:00",
      "speaker": "Doctor",
      "text": "You’re welcome. You handled this really well. Take care, and we’ll see you in clinic."
    },
    {
      "turn_number": 60,
      "time": "2181-03-29 08:22:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 61,
      "time": "2181-03-29 10:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check before discharge. How’s the pain?"
    },
    {
      "turn_number": 62,
      "time": "2181-03-29 10:01:00",
      "speaker": "Patient",
      "text": "Much better. I only took Tylenol once yesterday."
    },
    {
      "turn_number": 63,
      "time": "2181-03-29 10:03:00",
      "speaker": "Doctor",
      "text": "Excellent. And mood?"
    },
    {
      "turn_number": 64,
      "time": "2181-03-29 10:04:00",
      "speaker": "Patient",
      "text": "Stable. I’m a bit tired, but not anxious like before."
    },
    {
      "turn_number": 65,
      "time": "2181-03-29 10:06:00",
      "speaker": "Doctor",
      "text": "Good. Remember, if anything changes, don’t hesitate to call."
    },
    {
      "turn_number": 66,
      "time": "2181-03-29 10:08:00",
      "speaker": "Patient",
      "text": "I will. I’m ready to go home."
    },
    {
      "turn_number": 67,
      "time": "2181-03-29 10:10:00",
      "speaker": "Doctor",
      "text": "We’ll have your husband bring the car around. Take it easy, and follow up as scheduled."
    },
    {
      "turn_number": 68,
      "time": "2181-03-29 10:12:00",
      "speaker": "Patient",
      "text": "I will. Thanks again."
    },
    {
      "turn_number": 69,
      "time": "2181-03-29 12:00:00",
      "speaker": "Doctor",
      "text": "Final check—your discharge papers are ready. Lab order is included. Any last questions?"
    },
    {
      "turn_number": 70,
      "time": "2181-03-29 12:02:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got it all. Just glad to be going home."
    },
    {
      "turn_number": 71,
      "time": "2181-03-29 12:04:00",
      "speaker": "Doctor",
      "text": "You’ve done great. We’ll see you in clinic soon."
    },
    {
      "turn_number": 72,
      "time": "2181-03-29 12:06:00",
      "speaker": "Patient",
      "text": "Thank you, Doctor."
    },
    {
      "turn_number": 73,
      "time": "2181-03-29 14:00:00",
      "speaker": "Doctor",
      "text": "Just confirming—you’ve reviewed the discharge instructions?"
    },
    {
      "turn_number": 74,
      "time": "2181-03-29 14:02:00",
      "speaker": "Patient",
      "text": "Yes, I’ll get the labs done and follow up next week."
    },
    {
      "turn_number": 75,
      "time": "2181-03-29 14:04:00",
      "speaker": "Doctor",
      "text": "Perfect. And remember—no Seroquel or temazepam."
    },
    {
      "turn_number": 76,
      "time": "2181-03-29 14:06:00",
      "speaker": "Patient",
      "text": "Got it. Lorazepam only if I need it."
    },
    {
      "turn_number": 77,
      "time": "2181-03-29 14:08:00",
      "speaker": "Doctor",
      "text": "Exactly. You’re all set."
    },
    {
      "turn_number": 78,
      "time": "2181-03-29 16:00:00",
      "speaker": "Patient",
      "text": "Doctor, one last thing—should I restart my Plavix?"
    },
    {
      "turn_number": 79,
      "time": "2181-03-29 16:02:00",
      "speaker": "Doctor",
      "text": "Yes, you can restart clopidogrel tomorrow. You were off it before the biopsy."
    },
    {
      "turn_number": 80,
      "time": "2181-03-29 16:04:00",
      "speaker": "Patient",
      "text": "Thank you. I almost forgot."
    },
    {
      "turn_number": 81,
      "time": "2181-03-29 16:06:00",
      "speaker": "Doctor",
      "text": "No problem. That’s why we’re here. Take care."
    },
    {
      "turn_number": 82,
      "time": "2181-03-29 18:00:00",
      "speaker": "Doctor",
      "text": "Final goodbye. You’re officially discharged. We’ll see you in clinic."
    },
    {
      "turn_number": 83,
      "time": "2181-03-29 18:02:00",
      "speaker": "Patient",
      "text": "Thank you so much for everything."
    },
    {
      "turn_number": 84,
      "time": "2181-03-29 18:04:00",
      "speaker": "Doctor",
      "text": "You’re very welcome. Get some rest and take it easy."
    },
    {
      "turn_number": 85,
      "time": "2181-03-29 18:06:00",
      "speaker": "Patient",
      "text": "I will. Goodbye!"
    }
  ],
  "summary": {
    "admission_start": "2181-03-17 08:43:00",
    "admission_end": "2181-03-29 19:50:00",
    "summary_paragraph": "A woman with a history of living donor liver transplant for primary sclerosing cholangitis presented with sudden-onset right upper quadrant abdominal pain and elevated liver enzymes. Initial imaging showed patent hepatic vasculature but no clear cause. A transjugular liver biopsy revealed mild acute cellular rejection, prompting treatment with high-dose steroids, increased immunosuppression, and valganciclovir. Despite therapy, liver enzymes continued to rise, leading to a second biopsy that showed resolution of rejection but mild steatosis. The transaminitis was attributed to medication effects, particularly Seroquel and temazepam, both of which were discontinued. Steroid-induced mood symptoms were managed with Ativan and Seroquel, but the latter was stopped due to liver concerns. The patient improved clinically, with pain control and stabilization of labs. She was discharged on a tapering steroid regimen, adjusted immunosuppression, insulin for steroid-induced hyperglycemia, and instructions to restart clopidogrel. Follow-up was arranged for lab monitoring and outpatient evaluation.",
    "problems": [
      "Liver transplant rejection",
      "Right upper quadrant pain",
      "Abnormal liver function tests",
      "Steroid induced mood disorder",
      "Fatty liver",
      "Adverse effect of antipsychotics",
      "Adverse effect of benzodiazepines",
      "Hypertension",
      "Type 2 diabetes mellitus without complications",
      "Gastro-esophageal reflux disease without esophagitis",
      "Hypothyroidism, unspecified",
      "Celiac disease",
      "Long term (current) use of antithrombotics/antiplatelets"
    ]
  }
}
